def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if not isinstance(cmd, tuple) or not all(isinstance(item, str) for item in cmd):
        raise ValueError("The input must be a tuple of strings.")

    normalized_cmd = []

    for item in cmd:
        if item.startswith('#!/'):
            normalized_cmd.append(item[2:].strip())
        else:
            normalized_cmd.append(item)

    return tuple(normalized_cmd)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    normalized_cmd = []
    for c in cmd:
        # Check if the command is a shebang
        if c.startswith('#!'):
            # Normalize the shebang for Windows
            shebang_parts = c.split('\n')
            normalized_shebang = shebang_parts[0] + ' ' + os.path.normpath(shebang_parts[1])
            normalized_cmd.append(normalized_shebang)
        else:
            # Use the original command if it's not a shebang
            normalized_cmd.append(c)

    return tuple(normalized_cmd)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if len(cmd) != 2:
        raise ValueError("Command list must contain exactly two elements")

    if platform.system() == "Windows":
        # Fix for the first problem on windows: https://bugs.python.org/issue8557
        cmd[1] = cmd[1].replace('\\', '/').replace(' ', '%20')

        # Fix for the second problem on windows: windows does not parse shebangs
        if cmd[0].startswith('#!'):
            cmd[0] = 'cmd /E:ON /C "' + cmd[0].strip('#!') + '"'

    return cmd

