    if not sql or not params:
        raise ValueError("Both SQL and parameters must be provided.")
    if self._sql_params.in_style in ['named', 'named_colons', 'named_questionmark', 'named_triplets']:
        if not isinstance(params, dict):
            raise ValueError("For named parameter styles, 'params' must be a dictionary.")
    else:
        if not isinstance(params, (list, tuple)):
            raise ValueError("For ordinal parameter styles, 'params' must be a list or tuple.")
    formatted_sql, converted_params = self.convert_parameters(sql, params)
    return formatted_sql, converted_params

