    digest_mismatched = {}

    for version in version_dirs:
        try:
            inventory_path = os.path.join(self.version_dir, version)
            in_dir_contents = os.listdir(inventory_path)
            for item in in_dir_contents:
                if item.startswith('Inventory-'):
                    version_number = int(item[len('Inventory-'):])
                    if version_number not in inventories:
                        inventories[version_number] = []
                    inventories[version_number].append(item)
            digest_path = os.path.join(self.version_dir, f'Inventory-{version}.digests')
            with open(digest_path, 'r') as f:
                for line in f:
                    ident, digest = line.strip().split(',')
                    digest_mismatched[(ident, version_number)] = digest
        except FileNotFoundError:
            pass

    # Check each version to ensure all dependencies are present in the root inventory
    if self.validate_dependencies(self.root_inventory, inventories):
        print("Versions are correctly validated!")
    else:
        print("Some versions have dependencies that are not present in the root inventory.")

