            for digests in inventory_content_digests:
                if digests not in root_inventory_content_digests:
                    inventory_errors.append((version_dir, f'content digest {digests} not found in root inventory'))

        except FileNotFoundError as e:
            inventory_errors.append((version_dir, str(e)))

        except IOError as e:
            inventory_errors.append((version_dir, str(e)))

    if inventory_errors:
