def paging(response, max_results):
    if not isinstance(response, list) or not isinstance(max_results, int) or max_results <= 0:
        raise ValueError("Invalid arguments")

    if len(response) <= max_results:
        yield response
        return

    current_page = 0
    all_pages = []
    while current_page * max_results < len(response):
        end_index = min((current_page + 1) * max_results, len(response))
        page = response[current_page * max_results:end_index]
        all_pages.append(page)
        current_page += 1

    for page in all_pages:
        yield page

