def size_to_bytes(size: str) -> int:
    # Remove any whitespace
    size = size.replace(" ", "")

    try:
        # See if the size ends with a 'B' or 'b' for binary
        if size[-1].lower() == 'b':
            multipler = 1024
        # Otherwise, assume it's decimal
        else:
            multipler = 1

        # Split into number and unit
        parts = size.split()
        num = int(parts[0])
        units = parts[1].lower()

        # Convert to bytes
        if units == 'kb':
            return num * multipler
        elif units == 'mb':
            return num * multipler ** 2
        elif units == 'gb':
            return num * multipler ** 3
        elif units == 'tb':
            return num * multipler ** 4
        elif units == 'pb':
            return num * multipler ** 5
        else:
            raise ValueError(f"Unsupported unit: {units}")
    except ValueError as e:
        raise ValueError(f"Invalid size: {size}. {e}")
    except IndexError as e:
        raise ValueError(f"Invalid size format: {size}. {e}")

