    if size is None:
        raise ValueError("Size cannot be None")
    if not isinstance(size, str):
        raise TypeError("Size must be a string")
    if not re.match("^[0-9]+([KMG]iB)$", size, re.IGNORECASE):
        raise ValueError("Invalid file size format, expected 'N[KMG]iB'")

    size = size.upper()
    magnitude = 0
    for unit in ["", "K", "M", "G"]:
        if unit in size:
            size = size.replace(unit, "")
            magnitude += 1

    value = float(size)
    if magnitude == 0:
        return int(value)
    power = 2 ** (magnitude * 10)
    return int(value * power)

