    for i in range(len(vertices)):
        first, second = (vertices[(i - 1) % len(vertices)], vertices[i])
        third = (vertices[(i + 1) % len(vertices)], vertices[i])
        triangles.append((first, second, third))

    return triangles

def vertex3tuple(vertices):
    if not vertices or len(vertices) < 3:
        raise ValueError("Input list must contain at least 3 vertices")

    vertices_2d = vertices[:]
    if len(vertices_2d) % 2 != 0:
        vertices_2d.append(vertices_2d[0])  # Duplicate last vertex for closed polygon

    vertices_3d = []
    for i in range(len(vertices_2d) - 2):
        edges = vertices_2d[i:i+3]
        avg = [(p1[0] + p2[0] + p3[0]) / 3 for p1, p2, p3 in zip(edges)]
        vertices_3d.extend([tuple(avg) for _ in range(2)])  # Extend with 2 opposite vertices

    return vertices_3d

