def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("alphabet must not be empty")
    if number < 0:
        raise ValueError("number must be non-negative")
    if padding is not None and padding < 0:
        raise ValueError("padding must be non-negative")

    result = []
    while number > 0:
        digit = number % len(alphabet)
        result.append(alphabet[digit])
        number //= len(alphabet)

    if padding is not None:
        while len(result) < padding:
            result.append(alphabet[0])

    return ''.join(reversed(result))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not all(char in alphabet for char in str(number)):
        raise ValueError("Number contains characters not in the alphabet")

    if not alphabet:
        raise ValueError("Alphabet must not be empty")

    if padding is None or number < 0:
        padding = len(alphabet)

    digits = [number]
    while digits[-1] >= len(alphabet):
        digits.append(digits[-1] // len(alphabet))

    result = ''
    while digits:
        result = alphabet[digits.pop() % len(alphabet)] + result

    return result

def int_to_string(number: int, alphabet: list, padding: Optional[int] = None) -> str:
    """Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int) or number < 0:
        raise ValueError("Input must be a non-negative integer.")
    if not isinstance(alphabet, list):
        raise ValueError("Alphabet must be a list.")
    if padding is not None and padding < 0:
        raise ValueError("Padding must be a non-negative integer.")

    result = []
    if padding and number == 0:
        result.append(alphabet[0] * padding)
    else:
        while number > 0:
            index = number % len(alphabet)
            result.append(alphabet[index])
            number //= len(alphabet)

    result.reverse()
    return ''.join(result)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")

    if number < 0 or number >= len(alphabet):
        raise ValueError("Number out of bounds")

    ascii_str = ""

    if padding is None:
        while number > 0:
            ascii_str += alphabet[number % len(alphabet)]
            number //= len(alphabet)
    else:
        while number > 0 and padding > 0:
            ascii_str += alphabet[number % len(alphabet)]
            number //= len(alphabet)
            padding -= 1

    return ascii_str[::-1]

