def is_local(host):
    if not host:
        raise ValueError("Host cannot be null")
    try:
        return socket.gethostbyname(host) == '127.0.0.1'
    except socket.gaierror:
        return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str):
        raise ValueError("The host must be a string")

    try:
        # Check if the host is the localhost
        if host == "localhost":
            return True
        elif host.startswith("127."):
            return True

        # Check if the host is reachable
        else:
            sock = socket.create_connection(('localhost', 80), timeout=1)
            sock.close()
            return True
    except (ConnectionRefusedError, TimeoutError):
        return False

def is_local(host):
    try:
        # Attempt to create a socket to a local address
        socket.create_connection((host, 80))
        return True
    except OSError:
        # If the socket creation fails, assume it is not a localhost
        return False

def is_local(host):
    if not isinstance(host, str):
        raise ValueError("The host must be a string")

    try:
        info = socket.gethostbyname(host)
        return info == socket.gethostname()
    except socket.error as e:
        raise Exception(f"Hostname {host} is not valid", e)

