def make_find_paths(find_paths):
    # Helper function to convert path fragments to glob patterns
    def fragment_to_glob(fragment):
        if fragment.startswith('pp:root'):
            return fragment
        else:
            return f'sh:{re.escape(fragment)}/**/*.'

    # Map each path fragment to a glob pattern
    glob_paths = [fragment_to_glob(f) if not re.match(r'^pp:', f) else f for f in find_paths]

    return glob_paths

