def subprocess_run_helper(func, *args, timeout, extra_env=None):
    if not callable(func):
        raise ValueError("The func parameter must be a callable function.")
    if not args:
        raise ValueError("The args parameter must be provided.")

    if timeout is None or timeout < 0:
        raise ValueError("The timeout parameter must be a non-negative integer.")

    if extra_env is None:
        extra_env = {}

    try:
        return subprocess.run(args, timeout=timeout, check=True, executable=func.__module__.endswith('.py') and sys.executable or func.__name__, env=extra_env)
    except subprocess.TimeoutError:
        print("Timeout occurred.")
        return None
    except subprocess.CalledProcessError as e:
        print(f"Function failed with error: {e}")
        return None
    except FileNotFoundError:
        print("Function module not found.")
        return None

