        raise ValueError("The property input must be a valid rdflib URIRef.")

    if roots is None:
        roots = set()

    # Get all the subjects (nodes) that are objects of the specified property
    subject_objects = graph.objects(None, prop)

    # Store the subjects
    seen_subjects = set(subject_objects)

    # Expand the subjects to their root nodes by following any links
    while len(seen_subjects) < len(subject_objects):
        new_subjects = set()
        for subject in seen_subjects:
            for URI, node in subject_objects:
                if URI == prop:
                    new_subjects.add(node)
        seen_subjects.update(new_subjects)

    # Return the list of unique roots
    return seen_subjects

