    """
    # Handle case where no bases are provided
    if not bases:
        return type(None)

    # Use explicitly provided metaclass if specified
    if explicit_mc is not None:
        return explicit_mc

    # Attempt to inherit from one of the base classes
    for base in bases:
        if hasattr(base, '__metaclass__'):
