        elif current_tag:
            if replacer:
                current_tag = replacer(current_tag)
        else:
            replaced_text = text[:text.index(char)] + (replacer(current_tag) if replacer else current_tag) + text[text.index(char) + 1:]

    if current_tag:
        tags.add(current_tag)

    return tags, replaced_text

