def process_text_links(text):
    # Function to add specific attributes to links
    def add_link_attributes(tag):
        return f'<a target="_blank" rel="noopener noreferrer" href="{tag.attrib["href"]}">{tag.text}</a>'

    # Find all text link tags in the HTML
    text_links = re.findall(r'<a\s+href="(.*?)">(.*?)</a>', text)

    # Process each text link tag and replace it with the modified version
    for href_text, link_text in text_links:
        text = text.replace(f'<a href="{href_text}">{link_text}</a>', add_link_attributes(re.split(r'\s+', href_text)[0]))

    return text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    # Split the text into links and non-links
    links, non_links = [], []
    current_text = ''
    for char in text:
        if char == '[':
            # Start of a link
            link_start = text.index(']', char)
            link = text[char + 1:link_start]
            non_links.append(current_text.strip())
            current_text = link
        else:
            current_text += char
    non_links.append(current_text.strip())

    # Process each link and add attributes
    processed_links = []
    for link in links:
        if '://' in link:
            # Full URL, keep as is
            processed_links.append(link)
        else:
            # Relative link, try to resolve with base URL
            base_url = 'http://' + urlparse(text).netloc
            full_url = f'{base_url}{link}'
            processed_links.append(full_url)

    # Linkify textual links
    for i, link in enumerate(processed_links):
        processed_links[i] = link.replace('[', '<a').replace(']', '>')

    return ' '.join(non_links) + ' ' + ' '.join(processed_links)

