def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    playbook_dir = os.path.dirname(playbook_path)
    args = ['ansible-playbook']
    if verbose is not None:
        args.append('-v' + str(verbose))
    if extra_vars is not None:
        args.extend(['--extra-vars=', str(extra_vars)])
    args.extend(['-i', f'{ir_workspace.workdir}/{ir_plugin.get_inventory()}'])
    args.append(playbook_path)
    if ansible_args is not None:
        args.extend(ansible_args)

    try:
        result = subprocess.run(args, cwd=playbook_dir, check=True, capture_output=True, text=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        if e.stderr:
            return e.stderr
        return e.stdout if e.stdout else ''

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    try:
        command = ['ansible-playbook',
                  '-i', os.path.join(ir_workspace.directory, 'inventory/inventory'),
                  playbook_path]

        if verbose is not None:
            command += ['-vv']
        elif verbose == 0:
            command += ['-q']

        if extra_vars is not None:
            for key, value in extra_vars.items():
                command += ['--extra-vars', f'{key}="{value}"']

        if ansible_args is not None:
            for key, value in ansible_args.items():
                command += ['--', key, value]

        result = subprocess.run(command, capture_output=True, text=True, check=True)

        return result.stdout
    except FileNotFoundError:
        return "Ansible command not found."
    except subprocess.CalledProcessError as e:
        return f"Ansible playbook execution failed with error: {e.stderr}"
    except Exception as e:
        return f"An error occurred: {e}"

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    # Ensure required parameters are provided
    if not playbook_path:
        raise ValueError(" playbook_path is required")

    # Construct the ansible command
    command = ['ansible-playbook', playbook_path]
    if verbose is not None:
        command.extend(['-vv' if verbose else '-q'])
    if extra_vars:
        extra_vars_str = ' '.join(f'{k}={v}' for k, v in extra_vars.items())
        command.extend(['-e', extra_vars_str])
    if ansible_args:
        ansible_args_str = ' '.join([f'{k}={v}' for k, v in ansible_args.items()])
        command.extend(['--extra-vars', ansible_args_str])

    # Execute the ansible command
    try:
        subprocess.run(command, check=True, living=True, encoding='utf-8')
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Failed to execute ansible-playbook: Exit code {e.returncode}")
        else:
            print(f"Failed to execute ansible-playbook: {e}")

