        if os.name == 'nt':
            # For Windows
            if platform.architecture()[0] == '64bit':
                self.cfg_path = os.path.join(os.getenv('APPDATA'), 'my_config.ini')
            else:
                self.cfg_path = os.path.join(os.getenv('LOCALAPPDATA'), 'my_config.ini')
        elif os.name == 'posix':
            # For Linux/Mac
            self.cfg_path = os.path.join('/etc', 'my_config.ini')
        else:
            raise ValueError("Unsupported operating system")
        if self.cfg_path is not None:
            os.environ['MY_CFG_PATH'] = self.cfg_path
        else:
            raise ValueError("Could not set config path")

